const form=document.getElementById("brickForm"),result=document.getElementById("result"),PER_M2={"0.5":51,1:102,"1.5":153,2:204};form&&form.addEventListener("submit",t=>{t.preventDefault();const e=parseFloat(document.getElementById("length").value)||0,s=parseFloat(document.getElementById("height").value)||0,n=document.getElementById("thickness").value,a=parseFloat(document.getElementById("reserve").value)||0;if(e<=0||s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите длину и высоту больше нуля.</p>';return}const l=e*s,c=PER_M2[n]||102,i=l*c,o=Math.ceil(i*(1+a/100)),r={"0.5":"В полкирпича",1:"В один кирпич","1.5":"В полтора кирпича",2:"В два кирпича"};result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Площадь кладки</span><span class="val">${fmt(l)} м²</span></div>
        <div class="item"><span>Кирпичей без запаса</span><span class="val">${fmt(i)} шт</span></div>
        <div class="item total"><span>Кирпичей с запасом ${fmt(a)}%</span><span class="val">${fmt(o)} шт</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Толщина: ${r[n]}, ≈ ${c} шт/м².</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:0}).format(t)}
